fn frame(t: i32) {
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut seed: i32 = 313;
        let mut r: i32 = 0;
        while r < 12 {
            seed = seed * 1103515245 + 12345;
            host::display::state_set(8 + r, (seed >> 8) & 65535);
            host::display::state_set(20 + r, 0);
            r = r + 1;
        }
        host::display::state_set(2, seed);
    }
    let mut tree = [0; 12];
    let mut fire = [0; 12];
    let mut r: i32 = 0;
    while r < 12 {
        tree[r] = host::display::state_get(8 + r);
        fire[r] = host::display::state_get(20 + r);
        r = r + 1;
    }
    if t % 5 == 0 {
        let mut seed: i32 = host::display::state_get(2);
        let mut nf = [0; 12];
        r = 0;
        while r < 12 {
            let mut nb: i32 = ((fire[r] << 1) | (fire[r] >> 1)) & 65535;
            if r > 0 { nb = nb | fire[r - 1]; }
            if r < 11 { nb = nb | fire[r + 1]; }
            nf[r] = nb & tree[r];
            r = r + 1;
        }
        r = 0;
        while r < 12 {
            tree[r] = tree[r] & (65535 ^ nf[r]);
            fire[r] = nf[r];
            r = r + 1;
        }
        let mut k: i32 = 0;
        while k < 3 {
            seed = seed * 1103515245 + 12345;
            let rr: i32 = ((seed >> 16) & 4095) % 12;
            let cc: i32 = ((seed >> 4) & 4095) % 16;
            let bit: i32 = 1 << cc;
            if (tree[rr] & bit) == 0 && (fire[rr] & bit) == 0 {
                tree[rr] = tree[rr] | bit;
            }
            k = k + 1;
        }
        seed = seed * 1103515245 + 12345;
        if ((seed >> 16) & 63) < 2 {
            let rr: i32 = ((seed >> 4) & 4095) % 12;
            let cc: i32 = ((seed >> 9) & 4095) % 16;
            let bit: i32 = 1 << cc;
            if (tree[rr] & bit) == bit {
                fire[rr] = fire[rr] | bit;
                tree[rr] = tree[rr] & (65535 ^ bit);
            }
        }
        r = 0;
        while r < 12 {
            host::display::state_set(8 + r, tree[r]);
            host::display::state_set(20 + r, fire[r]);
            r = r + 1;
        }
        host::display::state_set(2, seed);
    }
    host::display::clear(0x080806);
    let mut trees: i32 = 0;
    r = 0;
    while r < 12 {
        let mut c: i32 = 0;
        while c < 16 {
            let mut col: i32 = 0x141410;
            if ((fire[r] >> c) & 1) == 1 {
                col = if ((t + r + c) & 1) == 0 { 0xff8020 } else { 0xffc040 };
            } else if ((tree[r] >> c) & 1) == 1 {
                col = 0x207830;
                trees = trees + 1;
            }
            host::display::fill_rect(64 + c * 24, 90 + r * 24, 22, 22, col);
            c = c + 1;
        }
        r = r + 1;
    }
    host::display::draw_string(64, 40, "TREES", 0x40a050, 2);
    host::display::draw_number(160, 40, trees, 0xffffff, 2);
    host::display::present();
}
